// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _runTest(address payer, uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(payer != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        uint256 beforeRecorded;
        try c.balances(payer) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint256 beforeContractBal = address(c).balance;
        payer = address(this);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 afterRecorded;
        try c.balances(payer) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint256 afterContractBal = address(c).balance;
        assertTrue(afterRecorded == beforeRecorded + depositAmount && afterContractBal == beforeContractBal + depositAmount);
    }

    function testFuzz_runTest(address payer, uint256 depositAmount) public {
        _runTest(payer, depositAmount);
    }

    receive() external payable {}
}
